// ---- CONFIG (our shared secret with the "client system") ----
const SHARED_SECRET = "my-super-secret-key-2026"; // we'll change this to something stronger later
const MAX_AGE_SECONDS = 300; // 5 minutes — reject anything older

// ---- GET INCOMING DATA ----
const headers = $input.item.json.headers;
const body = $input.item.json.body;

const receivedToken = headers['x-webhook-token'];
const receivedTimestamp = headers['x-webhook-timestamp'];
const receivedSignature = headers['x-webhook-signature'];

let isValid = true;
let reason = "";

// ---- CHECK 1: TOKEN ----
if (receivedToken !== SHARED_SECRET) {
  isValid = false;
  reason = "Invalid or missing token";
}

// ---- CHECK 2: TIMESTAMP (replay protection) ----
if (isValid) {
  const now = Math.floor(Date.now() / 1000);
  const requestTime = parseInt(receivedTimestamp, 10);
  const age = now - requestTime;

  if (isNaN(requestTime) || age > MAX_AGE_SECONDS || age < 0) {
    isValid = false;
    reason = "Request timestamp too old or invalid (possible replay attack)";
  }
}

// ---- CHECK 3: SIGNATURE ----
if (isValid) {
  const crypto = require('crypto');
  const payloadString = JSON.stringify(body) + receivedTimestamp;
  const expectedSignature = crypto
    .createHmac('sha256', SHARED_SECRET)
    .update(payloadString)
    .digest('hex');

  if (receivedSignature !== expectedSignature) {
    isValid = false;
    reason = "Signature mismatch (data may have been tampered with)";
  }
}

// ---- OUTPUT ----
return {
  isValid,
  reason: reason || "All checks passed",
  originalBody: body
};
